function isIPv4(s: string): boolean {
  const parts = s.split(".");
  if (parts.length !== 4) return false;
  for (const p of parts) {
    if (!/^(0|[1-9][0-9]{0,2})$/.test(p)) return false;
    if (Number(p) > 255) return false;
  }
  return true;
}

const HEX_GROUP = /^[0-9A-Fa-f]{1,4}$/;

function isIPv6(text: string): boolean {
  let addr = text;
  const pct = text.indexOf("%");

  if (pct !== -1) {
    addr = text.slice(0, pct);
    const zone = text.slice(pct + 1);
    if (!/^[0-9A-Za-z]+$/.test(zone)) return false;
    // Zone index is only permitted after a link-local address (fe80::/10).
    const firstGroup = addr.split(":")[0];
    if (!/^[fF][eE][89abAB][0-9a-fA-F]$/.test(firstGroup)) return false;
  }

  if (!parseIPv6Address(addr)) return false;
  return true;
}

function parseIPv6Address(addr: string): boolean {
  // An embedded dotted IPv4 tail is only allowed as the final token.
  // Replace it with two zero groups so the rest can be validated as pure hex.
  const lastColon = addr.lastIndexOf(":");
  const lastToken = addr.slice(lastColon + 1);
  if (lastToken.includes(".")) {
    if (!isIPv4(lastToken)) return false;
    addr = addr.slice(0, lastColon + 1) + "0:0";
  }

  // Dotted notation anywhere else is invalid.
  if (addr.includes(".")) return false;

  const dbl = addr.indexOf("::");
  if (dbl !== -1) {
    // At most one "::" (this also rejects ":::").
    if (addr.indexOf("::", dbl + 1) !== -1) return false;

    const left = addr.slice(0, dbl);
    const right = addr.slice(dbl + 2);
    const leftGroups = left === "" ? [] : left.split(":");
    const rightGroups = right === "" ? [] : right.split(":");

    for (const g of leftGroups) {
      if (!HEX_GROUP.test(g)) return false;
    }
    for (const g of rightGroups) {
      if (!HEX_GROUP.test(g)) return false;
    }

    // "::" must stand for at least one zero group.
    return leftGroups.length + rightGroups.length <= 7;
  }

  const groups = addr.split(":");
  if (groups.length !== 8) return false;
  for (const g of groups) {
    if (!HEX_GROUP.test(g)) return false;
  }
  return true;
}

export function solve(text: string): boolean {
  let s = text;
  if (s.startsWith("(") && s.endsWith(")")) {
    s = s.slice(1, -1);
  }

  const m = /^([+\-\u2212]?\d+(?:\.\d+)?),[ ]*([+\-\u2212]?\d+(?:\.\d+)?)$/.exec(s);
  if (!m) return false;

  const lat = parseSigned(m[1]);
  const lon = parseSigned(m[2]);

  return lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180;
}

function parseSigned(t: string): number {
  const neg = t[0] === "-" || t[0] === "\u2212";
  const body = /^[+\-\u2212]/.test(t) ? t.slice(1) : t;
  const v = Number(body);
  return neg ? -v : v;
}

export function solve(issn: string): boolean {
  // Format: NNNN-NNNC or NNNNNNNC, where C is a digit or X/x.
  const match = /^(\d{4})-?(\d{3})([\dXx])$/.exec(issn);
  if (match === null) {
    return false;
  }

  const chars = match[1] + match[2] + match[3]; // 8 characters, no hyphen

  // Weights are 8, 7, ..., 2 for the first seven digits and 1 for the check
  // character. Using 0-based index i with weight (8 - i) gives exactly this.
  let sum = 0;
  for (let i = 0; i < 8; i++) {
    const c = chars[i];
    const value = c === "X" || c === "x" ? 10 : Number(c);
    sum += (8 - i) * value;
  }

  return sum % 11 === 0;
}

export function solve(a: string, b: string): number {
  const n = a.length;
  const m = b.length;
  if (n === 0) return m;
  if (m === 0) return n;

  let prev = new Int32Array(m + 1);
  let curr = new Int32Array(m + 1);
  for (let j = 0; j <= m; j++) prev[j] = j;

  for (let i = 1; i <= n; i++) {
    curr[0] = i;
    const ca = a.charCodeAt(i - 1);
    for (let j = 1; j <= m; j++) {
      const cost = ca === b.charCodeAt(j - 1) ? 0 : 1;
      let v = prev[j - 1] + cost;
      const del = prev[j] + 1;
      if (del < v) v = del;
      const ins = curr[j - 1] + 1;
      if (ins < v) v = ins;
      curr[j] = v;
    }
    const tmp = prev;
    prev = curr;
    curr = tmp;
  }

  return prev[m];
}

export function solve(doc: unknown, pointer: string): unknown {
  if (pointer === "") {
    return doc;
  }
  if (!pointer.startsWith("/")) {
    throw new Error(`Invalid JSON Pointer: must be empty or start with "/": ${JSON.stringify(pointer)}`);
  }

  const tokens = pointer.slice(1).split("/");
  let current: unknown = doc;

  for (const raw of tokens) {
    // RFC 6901: decode ~1 to "/" first, then ~0 to "~".
    const key = raw.replace(/~1/g, "/").replace(/~0/g, "~");

    if (Array.isArray(current)) {
      // Array index: "0" or a non-zero-leading digit sequence. "-" and others are not existing elements.
      if (!/^(0|[1-9][0-9]*)$/.test(key)) {
        return undefined;
      }
      const index = Number(key);
      if (index >= current.length) {
        return undefined;
      }
      current = current[index];
    } else if (typeof current === "object" && current !== null) {
      if (!Object.prototype.hasOwnProperty.call(current, key)) {
        return undefined;
      }
      current = (current as Record<string, unknown>)[key];
    } else {
      // Primitive or null: cannot descend further.
      return undefined;
    }
  }

  return current;
}

interface Ver {
  n: [number, number, number];
  pre: string[];
}

interface Bound {
  v: Ver;
  incl: boolean;
}

interface Part {
  M?: number;
  m: number;
  p: number;
  hasMinor: boolean;
  hasPatch: boolean;
  pre: string[];
}

function V(a: number, b: number, c: number, pre: string[] = []): Ver {
  return { n: [a, b, c], pre };
}

function ex(a: number, b: number, c: number): Bound {
  return { v: V(a, b, c, ['0']), incl: false };
}

function isWild(s: string | undefined): boolean {
  return s === undefined || s === '' || s === 'x' || s === 'X' || s === '*';
}

function parsePart(s: string): Part {
  const noBuild = s.split('+')[0];
  const dash = noBuild.indexOf('-');
  const core = dash === -1 ? noBuild : noBuild.slice(0, dash);
  const pre: string[] = dash === -1 ? [] : noBuild.slice(dash + 1).split('.');
  const parts = core.split('.');
  const M: number | undefined = isWild(parts[0]) ? undefined : Number(parts[0]);
  let hasMinor = false;
  let hasPatch = false;
  let m = 0;
  let p = 0;
  if (M !== undefined && !isWild(parts[1])) {
    hasMinor = true;
    m = Number(parts[1]);
    if (!isWild(parts[2])) {
      hasPatch = true;
      p = Number(parts[2]);
    }
  }
  return { M, m, p, hasMinor, hasPatch, pre };
}

function cmpVer(a: Ver, b: Ver): number {
  for (let i = 0; i < 3; i++) {
    if (a.n[i] !== b.n[i]) return a.n[i] < b.n[i] ? -1 : 1;
  }
  if (a.pre.length === 0 && b.pre.length === 0) return 0;
  if (a.pre.length === 0) return 1;
  if (b.pre.length === 0) return -1;
  const len = Math.min(a.pre.length, b.pre.length);
  for (let i = 0; i < len; i++) {
    const x = a.pre[i];
    const y = b.pre[i];
    const xn = /^\d+$/.test(x);
    const yn = /^\d+$/.test(y);
    if (xn && yn) {
      const d = Number(x) - Number(y);
      if (d !== 0) return d < 0 ? -1 : 1;
    } else if (xn) {
      return -1;
    } else if (yn) {
      return 1;
    } else if (x !== y) {
      return x < y ? -1 : 1;
    }
  }
  if (a.pre.length === b.pre.length) return 0;
  return a.pre.length < b.pre.length ? -1 : 1;
}

// Orders bounds by value; at equal values an exclusive bound is "smaller" (more restrictive).
function cmpBound(a: Bound, b: Bound): number {
  const c = cmpVer(a.v, b.v);
  if (c !== 0) return c;
  if (a.incl === b.incl) return 0;
  return a.incl ? 1 : -1;
}

function upperOf(op: string, q: Part): Bound | null {
  if (q.M === undefined) {
    return op === '<' || op === '>' ? ex(0, 0, 0) : null;
  }
  const M = q.M;
  const m = q.m;
  const pt = q.p;
  const pre = q.pre;
  const hasMinor = q.hasMinor;
  const hasPatch = q.hasPatch;

  switch (op) {
    case '':
    case '=':
      if (!hasMinor) return ex(M + 1, 0, 0);
      if (!hasPatch) return ex(M, m + 1, 0);
      return { v: V(M, m, pt, pre), incl: true };
    case '<':
      if (hasMinor && hasPatch) return { v: V(M, m, pt, pre), incl: false };
      return ex(M, m, 0);
    case '<=':
      if (hasMinor && hasPatch) return { v: V(M, m, pt, pre), incl: true };
      if (!hasMinor) return ex(M + 1, 0, 0);
      return ex(M, m + 1, 0);
    case '~':
      if (!hasMinor) return ex(M + 1, 0, 0);
      return ex(M, m + 1, 0);
    case '^':
      if (!hasMinor || M > 0) return ex(M + 1, 0, 0);
      if (!hasPatch || m > 0) return ex(0, m + 1, 0);
      return ex(0, 0, pt + 1);
    default:
      // '>' and '>=' impose no upper bound
      return null;
  }
}

// Returns the upper bounds contributed by one alternative (a comparator set or hyphen range).
function altBounds(alt: string): Bound[] {
  const hy = /^(\S+)\s+-\s+(\S+)$/.exec(alt);
  if (hy) {
    const b = upperOf('', parsePart(hy[2].replace(/^v/i, '')));
    return b ? [b] : [];
  }
  const norm = alt.replace(/(<=|>=|~>|<|>|=|~|\^)\s+/g, '$1');
  const out: Bound[] = [];
  for (const tok of norm.split(/\s+/)) {
    if (tok === '') continue;
    const mm = /^(<=|>=|~>|<|>|=|~|\^)?(.*)$/.exec(tok);
    if (!mm) continue;
    let op = mm[1] ?? '';
    if (op === '~>') op = '~';
    const body = mm[2].replace(/^v/i, '');
    const b = upperOf(op, parsePart(body));
    if (b) out.push(b);
  }
  return out;
}

export function solve(version: string, range: string): boolean {
  const vp = parsePart(version.trim());
  const v = V(vp.M ?? 0, vp.m, vp.p, vp.pre);

  for (const alt of range.split('||')) {
    const bounds = altBounds(alt.trim());
    // No upper bound in this alternative (e.g. "", "*", ">=1.0.0"): never exceeded.
    if (bounds.length === 0) return false;

    let min = bounds[0];
    for (const b of bounds) {
      if (cmpBound(b, min) < 0) min = b;
    }

    const c = cmpVer(v, min.v);
    if (min.incl ? c <= 0 : c < 0) return false;
  }
  return true;
}

export function solve(epochMs: number): string {
  if (!Number.isFinite(epochMs)) {
    throw new RangeError("epochMs must be a finite number");
  }

  // Floor before converting: Date truncates fractional milliseconds toward zero,
  // which would place pre-1970 fractional instants in the following second.
  const ms = Math.floor(epochMs);

  // toISOString() is always UTC and yields "YYYY-MM-DDTHH:mm:ss.sssZ"
  // (years outside 0000-9999 use the ECMAScript expanded form "±YYYYYY").
  // Strip the milliseconds and keep the trailing "Z".
  return new Date(ms).toISOString().replace(/\.\d{3}Z$/, "Z");
}

