export function solve(word: string, dictionary: string[]): string {
  if (dictionary.length === 0) {
    // "" can be a legitimate entry, so it cannot serve as a "not found" marker.
    throw new Error("solve: dictionary must contain at least one entry");
  }

  // Work on Unicode code points so astral characters (e.g. emoji) count as one.
  const source = Array.from(word);

  let best = dictionary[0];
  let bestDistance = Infinity;

  for (const entry of dictionary) {
    const chars = Array.from(entry);

    // The edit distance is at least the difference in lengths, so an entry whose
    // length gap already reaches the best distance cannot strictly improve on it.
    if (Math.abs(chars.length - source.length) >= bestDistance) continue;

    const distance = levenshtein(source, chars);

    // Strict "<" keeps the earlier entry on ties.
    if (distance < bestDistance) {
      best = entry;
      bestDistance = distance;
      if (distance === 0) break; // exact match: nothing can beat it
    }
  }

  return best;
}

/**
 * Levenshtein distance between two character sequences, computed row by row
 * in O(min(|x|, |y|)) extra space.
 */
function levenshtein(x: readonly string[], y: readonly string[]): number {
  // Distance is symmetric: iterate over the longer sequence and size the row
  // by the shorter one.
  const a = x.length >= y.length ? x : y;
  const b = x.length >= y.length ? y : x;

  // row[j] holds the distance between the processed prefix of `a` and b[0..j).
  const row: number[] = [];
  for (let j = 0; j <= b.length; j++) row.push(j);

  for (let i = 1; i <= a.length; i++) {
    let diagonal = row[0]; // previous row's value at j - 1
    row[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const above = row[j]; // previous row's value at j
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      row[j] = Math.min(above + 1, row[j - 1] + 1, diagonal + cost);
      diagonal = above;
    }
  }

  return row[b.length];
}

/** Binary min-heap over numbers. */
class MinHeap {
  private readonly items: number[] = [];

  get size(): number {
    return this.items.length;
  }

  push(value: number): void {
    const a = this.items;
    a.push(value);
    let i = a.length - 1;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (a[parent] <= a[i]) break;
      [a[parent], a[i]] = [a[i], a[parent]];
      i = parent;
    }
  }

  pop(): number {
    const a = this.items;
    const top = a[0];
    const last = a.pop() as number;
    if (a.length > 0) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const left = 2 * i + 1;
        const right = left + 1;
        let smallest = i;
        if (left < a.length && a[left] < a[smallest]) smallest = left;
        if (right < a.length && a[right] < a[smallest]) smallest = right;
        if (smallest === i) break;
        [a[smallest], a[i]] = [a[i], a[smallest]];
        i = smallest;
      }
    }
    return top;
  }
}

/**
 * Topologically sorts `nodes` so that for every edge [a, b], `a` comes before `b`.
 * Returns the lexicographically smallest valid order, comparing nodes by their
 * position in `nodes` (so an input that is already valid comes back unchanged).
 * Throws on duplicate node names, edges mentioning unknown nodes, and cycles
 * (self-loops included).
 */
export function solve(nodes: string[], edges: [string, string][]): string[] {
  const position = new Map<string, number>();
  nodes.forEach((node, i) => {
    if (position.has(node)) {
      throw new Error(`Duplicate node: "${node}"`);
    }
    position.set(node, i);
  });

  const successors: number[][] = nodes.map(() => []);
  const pending: number[] = nodes.map(() => 0); // unsatisfied incoming edges

  for (const [from, to] of edges) {
    const u = position.get(from);
    const v = position.get(to);
    if (u === undefined) {
      throw new Error(`Edge mentions unknown node: "${from}"`);
    }
    if (v === undefined) {
      throw new Error(`Edge mentions unknown node: "${to}"`);
    }
    successors[u].push(v);
    pending[v] += 1;
  }

  const ready = new MinHeap();
  for (let i = 0; i < nodes.length; i++) {
    if (pending[i] === 0) ready.push(i);
  }

  const result: string[] = [];
  while (ready.size > 0) {
    const u = ready.pop();
    result.push(nodes[u]);
    for (const v of successors[u]) {
      pending[v] -= 1;
      if (pending[v] === 0) ready.push(v);
    }
  }

  if (result.length !== nodes.length) {
    const stuck = nodes.filter((_, i) => pending[i] > 0);
    throw new Error(`Cycle detected; nodes that cannot be ordered: ${stuck.join(", ")}`);
  }
  return result;
}

const BASE64_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

/**
 * Decodes a standard base64 string (with optional '=' padding) into byte values (0-255).
 * Throws an Error if the input length is not a multiple of 4, or if the input contains
 * characters outside the base64 alphabet or misplaced padding.
 */
export function solve(text: string): number[] {
  if (text.length % 4 !== 0) {
    throw new Error(`Invalid base64 input: length ${text.length} is not a multiple of 4`);
  }

  // Strip up to two trailing '=' padding characters. Any '=' left in the data
  // portion is not in the alphabet, so the loop below rejects it.
  let end = text.length;
  if (end > 0 && text.charAt(end - 1) === "=") {
    end--;
  }
  if (end > 0 && text.charAt(end - 1) === "=") {
    end--;
  }

  const bytes: number[] = [];
  let acc = 0;     // bit accumulator
  let accBits = 0; // number of not-yet-emitted bits in acc

  for (let i = 0; i < end; i++) {
    const ch = text.charAt(i);
    const value = BASE64_ALPHABET.indexOf(ch);
    if (value < 0) {
      throw new Error(`Invalid base64 character '${ch}' at index ${i}`);
    }

    // Append 6 bits. Only the low 16 bits matter (at most 13 bits are ever pending).
    acc = ((acc << 6) | value) & 0xffff;
    accBits += 6;

    if (accBits >= 8) {
      accBits -= 8;
      bytes.push((acc >> accBits) & 0xff);
    }
  }

  // Any leftover bits (fewer than 8) are padding bits and are discarded.
  return bytes;
}

const SEMVER_PATTERN =
  /^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?$/;

interface ParsedVersion {
  raw: string;
  major: string;
  minor: string;
  patch: string;
  prerelease: string[] | null;
}

// Numeric comparison of digit strings without precision loss.
function compareNumeric(a: string, b: string): number {
  const x = a.replace(/^0+(?=\d)/, "");
  const y = b.replace(/^0+(?=\d)/, "");
  if (x.length !== y.length) return x.length < y.length ? -1 : 1;
  if (x === y) return 0;
  return x < y ? -1 : 1;
}

// Lexical comparison in ASCII (code unit) order.
function compareText(a: string, b: string): number {
  if (a === b) return 0;
  return a < b ? -1 : 1;
}

function compareIdentifiers(a: string, b: string): number {
  const aNumeric = /^\d+$/.test(a);
  const bNumeric = /^\d+$/.test(b);
  if (aNumeric && bNumeric) return compareNumeric(a, b);
  if (aNumeric) return -1; // numeric identifiers rank below alphanumeric ones
  if (bNumeric) return 1;
  return compareText(a, b);
}

// SemVer 2.0.0 precedence; build metadata is ignored.
function comparePrecedence(a: ParsedVersion, b: ParsedVersion): number {
  const core =
    compareNumeric(a.major, b.major) ||
    compareNumeric(a.minor, b.minor) ||
    compareNumeric(a.patch, b.patch);
  if (core !== 0) return core;

  if (a.prerelease === null || b.prerelease === null) {
    if (a.prerelease === null && b.prerelease === null) return 0;
    // A normal version outranks any prerelease with the same core.
    return a.prerelease === null ? 1 : -1;
  }

  const shared = Math.min(a.prerelease.length, b.prerelease.length);
  for (let i = 0; i < shared; i++) {
    const c = compareIdentifiers(a.prerelease[i], b.prerelease[i]);
    if (c !== 0) return c;
  }
  // With all shared identifiers equal, the longer list has higher precedence.
  return a.prerelease.length - b.prerelease.length;
}

export function solve(versions: string[]): string[] {
  const parsed: ParsedVersion[] = [];

  for (const raw of versions) {
    const match = SEMVER_PATTERN.exec(raw);
    if (match === null) continue; // only valid SemVer versions are returned
    parsed.push({
      raw,
      major: match[1],
      minor: match[2],
      patch: match[3],
      prerelease: match[4] === undefined ? null : match[4].split("."),
    });
  }

  // Precedence first; equal-precedence entries are ordered by their full string.
  parsed.sort((a, b) => comparePrecedence(a, b) || compareText(a.raw, b.raw));

  return parsed.map((v) => v.raw);
}

export function solve(text: string): string {
  // 1. UTF-8 encode. Lone surrogates become U+FFFD, matching TextEncoder.
  const bytes: number[] = [];
  const n = text.length;
  for (let i = 0; i < n; i++) {
    let cp = text.charCodeAt(i);
    if (cp >= 0xd800 && cp <= 0xdbff) {
      const next = i + 1 < n ? text.charCodeAt(i + 1) : 0;
      if (next >= 0xdc00 && next <= 0xdfff) {
        cp = 0x10000 + ((cp - 0xd800) << 10) + (next - 0xdc00);
        i++;
      } else {
        cp = 0xfffd;
      }
    } else if (cp >= 0xdc00 && cp <= 0xdfff) {
      cp = 0xfffd;
    }

    if (cp < 0x80) {
      bytes.push(cp);
    } else if (cp < 0x800) {
      bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
    } else if (cp < 0x10000) {
      bytes.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
    } else {
      bytes.push(
        0xf0 | (cp >> 18),
        0x80 | ((cp >> 12) & 0x3f),
        0x80 | ((cp >> 6) & 0x3f),
        0x80 | (cp & 0x3f)
      );
    }
  }

  // 2. Padding (FIPS 180-4, 5.1.1): append 0x80, zeros, then 64-bit big-endian bit length.
  const byteLen = bytes.length;
  const bitLenHi = Math.floor(byteLen / 0x20000000); // upper 32 bits of byteLen * 8
  const bitLenLo = (byteLen * 8) % 0x100000000; // lower 32 bits of byteLen * 8
  bytes.push(0x80);
  while (bytes.length % 64 !== 56) {
    bytes.push(0);
  }
  for (let s = 24; s >= 0; s -= 8) bytes.push((bitLenHi >>> s) & 0xff);
  for (let s = 24; s >= 0; s -= 8) bytes.push((bitLenLo >>> s) & 0xff);

  // 3. Compression (FIPS 180-4, 6.1.2).
  let h0 = 0x67452301;
  let h1 = 0xefcdab89;
  let h2 = 0x98badcfe;
  let h3 = 0x10325476;
  let h4 = 0xc3d2e1f0;
  const w: number[] = [];

  for (let off = 0; off < bytes.length; off += 64) {
    for (let t = 0; t < 16; t++) {
      const p = off + t * 4;
      w[t] = (bytes[p] << 24) | (bytes[p + 1] << 16) | (bytes[p + 2] << 8) | bytes[p + 3];
    }
    for (let t = 16; t < 80; t++) {
      const x = w[t - 3] ^ w[t - 8] ^ w[t - 14] ^ w[t - 16];
      w[t] = (x << 1) | (x >>> 31);
    }

    let a = h0;
    let b = h1;
    let c = h2;
    let d = h3;
    let e = h4;

    for (let t = 0; t < 80; t++) {
      let f: number;
      let k: number;
      if (t < 20) {
        f = (b & c) | (~b & d);
        k = 0x5a827999;
      } else if (t < 40) {
        f = b ^ c ^ d;
        k = 0x6ed9eba1;
      } else if (t < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8f1bbcdc;
      } else {
        f = b ^ c ^ d;
        k = 0xca62c1d6;
      }
      const temp = (((a << 5) | (a >>> 27)) + f + e + k + w[t]) >>> 0;
      e = d;
      d = c;
      c = ((b << 30) | (b >>> 2)) >>> 0;
      b = a;
      a = temp;
    }

    h0 = (h0 + a) >>> 0;
    h1 = (h1 + b) >>> 0;
    h2 = (h2 + c) >>> 0;
    h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0;
  }

  // 4. Serialize as 40 lowercase hex digits (big-endian words).
  const hs = [h0, h1, h2, h3, h4];
  let out = "";
  for (let i = 0; i < hs.length; i++) {
    const hex = (hs[i] >>> 0).toString(16);
    out += "00000000".slice(hex.length) + hex;
  }
  return out;
}

/** Validates an ISBN-10 whose spaces and hyphens have already been removed. */
function isValidIsbn10(code: string): boolean {
  if (!/^[0-9]{9}[0-9X]$/.test(code)) return false;

  let sum = 0;
  for (let i = 0; i < 10; i++) {
    const ch = code.charAt(i);
    const value = ch === 'X' ? 10 : ch.charCodeAt(0) - 48; // '0' is char code 48
    sum += (10 - i) * value; // weights 10, 9, ..., 1
  }
  return sum % 11 === 0;
}

/** Validates an ISBN-13 whose spaces and hyphens have already been removed. */
function isValidIsbn13(code: string): boolean {
  if (!/^[0-9]{13}$/.test(code)) return false;

  let sum = 0;
  for (let i = 0; i < 13; i++) {
    const digit = code.charCodeAt(i) - 48;
    sum += i % 2 === 0 ? digit : 3 * digit; // weights 1, 3, 1, 3, ...
  }
  return sum % 10 === 0;
}

export function solve(isbn: string, version?: 10 | 13): boolean {
  if (typeof isbn !== 'string') return false;

  const code = isbn.replace(/[ -]/g, ''); // spaces and hyphens are ignored

  const checkTen = version === undefined || version === 10;
  const checkThirteen = version === undefined || version === 13;

  return (checkTen && isValidIsbn10(code)) || (checkThirteen && isValidIsbn13(code));
}

export function solve(isin: string): boolean {
  // Format: 2 upper-case letters, 9 upper-case alphanumerics, 1 check digit.
  if (!/^[A-Z]{2}[A-Z0-9]{9}[0-9]$/.test(isin)) {
    return false;
  }

  // Convert letters to numbers (A=10 ... Z=35), keeping digits as they are.
  let digits = "";
  for (let i = 0; i < isin.length; i++) {
    const ch = isin.charAt(i);
    digits += ch >= "A" && ch <= "Z" ? String(ch.charCodeAt(0) - 55) : ch;
  }

  // Luhn algorithm over the whole digit string, scanning from the rightmost
  // digit (the check digit). Every second digit is doubled, and for doubled
  // values above 9 the digit sum is taken. Valid when the total is divisible by 10.
  let sum = 0;
  let doubleIt = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let d = digits.charCodeAt(i) - 48; // "0" is char code 48
    if (doubleIt) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    sum += d;
    doubleIt = !doubleIt;
  }

  return sum % 10 === 0;
}

export function solve(code: string): boolean {
  // Only ASCII digits are allowed
  if (!/^[0-9]+$/.test(code)) return false;

  const n = code.length;
  if (n !== 8 && n !== 13 && n !== 14) return false;

  const digitAt = (i: number): number => code.charCodeAt(i) - 48; // '0' is char code 48

  // Weights alternate 3, 1, 3, ... starting at the rightmost data digit
  // (the digit immediately before the check digit, index n - 2).
  let sum = 0;
  for (let i = 0; i < n - 1; i++) {
    const weight = i % 2 === 0 ? 3 : 1;
    sum += digitAt(n - 2 - i) * weight;
  }

  const check = (10 - (sum % 10)) % 10;
  return check === digitAt(n - 1);
}

export function solve(mac: string): boolean {
  // EUI-48 (6 octets) or EUI-64 (8 octets) with ':' or '-' separators.
  // The backreference \1 forces every separator to be the same character.
  const octets6 = /^[0-9A-Fa-f]{2}([:-])(?:[0-9A-Fa-f]{2}\1){4}[0-9A-Fa-f]{2}$/;
  const octets8 = /^[0-9A-Fa-f]{2}([:-])(?:[0-9A-Fa-f]{2}\1){6}[0-9A-Fa-f]{2}$/;

  // Dotted form (e.g. 0123.4567.89ab): 3 groups (EUI-48) or 4 groups (EUI-64) of 4 hex digits.
  const dotted = /^[0-9A-Fa-f]{4}(?:\.[0-9A-Fa-f]{4}){2,3}$/;

  return octets6.test(mac) || octets8.test(mac) || dotted.test(mac);
}

export function solve(issn: string): boolean {
  // Accept "NNNN-NNNC" or "NNNNNNNC"; the check character may be a digit or X/x.
  if (!/^\d{4}-?\d{3}[\dXx]$/.test(issn)) {
    return false;
  }

  const digits = issn.replace("-", ""); // 8 characters: 7 digits + check character

  // Weighted sum of the first seven digits, with weights 8 down to 2.
  let sum = 0;
  for (let i = 0; i < 7; i++) {
    sum += (8 - i) * Number(digits[i]);
  }

  // The check character has weight 1; 'X' or 'x' counts as 10.
  const check = digits[7];
  sum += check === "X" || check === "x" ? 10 : Number(check);

  return sum % 11 === 0;
}

export function solve(a: string, b: string): number {
  // Levenshtein distance over UTF-16 code units (charCodeAt).
  // The shorter string indexes the row, so only two rows of min(|a|, |b|) + 1 cells are allocated.
  let s = a; // longer (or equal length) string: outer loop
  let t = b; // shorter string: inner loop
  if (s.length < t.length) {
    s = b;
    t = a;
  }

  const n = s.length;
  const m = t.length;
  if (m === 0) return n;

  const tc = new Uint16Array(m);
  for (let j = 0; j < m; j++) tc[j] = t.charCodeAt(j);

  // prev[j] = distance between the first i code units of s and the first j code units of t
  let prev = new Int32Array(m + 1);
  let curr = new Int32Array(m + 1);
  for (let j = 0; j <= m; j++) prev[j] = j;

  for (let i = 1; i <= n; i++) {
    const sc = s.charCodeAt(i - 1);
    curr[0] = i;
    for (let j = 1; j <= m; j++) {
      const cost = sc === tc[j - 1] ? 0 : 1;
      let best = prev[j - 1] + cost; // match or substitution
      const del = prev[j] + 1; // deletion
      if (del < best) best = del;
      const ins = curr[j - 1] + 1; // insertion
      if (ins < best) best = ins;
      curr[j] = best;
    }
    const tmp = prev;
    prev = curr;
    curr = tmp;
  }

  return prev[m];
}

export function solve(installed: string[], range: string): string | null {
  // Non-string entries cannot be versions, so drop them before delegating.
  // Strings that are not valid semver are rejected by the matcher itself,
  // since Range.test returns false for them, so they never become the result.
  const candidates = installed.filter((v) => typeof v === 'string')

  const result = lib.maxSatisfying(candidates, range)
  return result === undefined ? null : result
}

