  if (labels.length < 2) return false;

  // Letters (international), digits, and hyphens; no leading or trailing hyphen.
  const labelPattern = /^[\p{L}0-9](?:[\p{L}0-9-]*[\p{L}0-9])?$/u;

  for (const label of labels) {
    const length = Array.from(label).length;
    if (length < 1 || length > 63) return false;
    if (!labelPattern.test(label)) return false;
  }

  const tld = labels[labels.length - 1];

  // TLD is either a punycode label (xn--...) or all letters (at least two characters).
  const punycodeTld = /^xn--[a-z0-9-]+$/i;
  const letterTld = /^\p{L}{2,}$/u;

  return punycodeTld.test(tld) || letterTld.test(tld);
}

export function solve(code: string): boolean {
  if (typeof code !== "string" || code.length !== 11) return false;

  // 3 owner letters, category identifier U/J/Z (any case), 7 digits (6 serial + check digit)
  if (!/^[A-Za-z]{3}[UJZ][0-9]{7}$/i.test(code)) return false;

  const s = code.toUpperCase();
  let sum = 0;

  for (let i = 0; i < 10; i++) {
    const c = s.charCodeAt(i);
    let value: number;

    if (c >= 48 && c <= 57) {
      // Digit: its own value
      value = c - 48;
    } else {
      // Letter: A = 10, skipping multiples of 11 (11, 22, 33)
      let n = 10 + (c - 65);
      if (n >= 11) n++;
      if (n >= 22) n++;
      if (n >= 33) n++;
      value = n;
    }

    sum += value * 2 ** i;
  }

  const check = (sum % 11) % 10;
  return check === s.charCodeAt(10) - 48;
}

export function solve(text: string, version?: 4 | 6): boolean {
  if (typeof text !== 'string') return false;

  const checkV4 = version === undefined || version === 4;
  const checkV6 = version === undefined || version === 6;

  if (checkV4 && isStrictIPv4(text)) return true;
  if (checkV6 && isIPv6WithOptionalZone(text)) return true;
  return false;
}

// lib.isIP's IPv4 pattern accepts leading zeros (e.g. "01.2.3.4"),
// which the task forbids, so those are rejected here before delegating.
function isStrictIPv4(s: string): boolean {
  const parts = s.split('.');
  if (parts.length !== 4) return false;
  for (const p of parts) {
    if (!/^(0|[1-9][0-9]{0,2})$/.test(p)) return false;
    if (Number(p) > 255) return false;
  }
  return lib.isIP(s, 4);
}

// Validates an IPv6 address, optionally followed by "%zone" when the
// address is link-local.
function isIPv6WithOptionalZone(s: string): boolean {
  const pct = s.indexOf('%');
  if (pct === -1) return isPlainIPv6(s);

  const addr = s.slice(0, pct);
  const zone = s.slice(pct + 1);
  if (!/^[A-Za-z0-9]+$/.test(zone)) return false;
  return isPlainIPv6(addr) && isLinkLocal(addr);
}

// Delegates the heavy lifting to lib.isIP, then enforces the strict
// leading-zero rule on any embedded dotted IPv4 tail.
function isPlainIPv6(s: string): boolean {
  if (!lib.isIP(s, 6)) return false;
  const tail = s.slice(s.lastIndexOf(':') + 1);
  if (tail.indexOf('.') !== -1) return isStrictIPv4(tail);
  return true;
}

// Link-local unicast: fe80::/10, i.e. first group in 0xfe80..0xfebf.
function isLinkLocal(addr: string): boolean {
  const first = addr.split(':')[0];
  if (!/^[0-9a-fA-F]{1,4}$/.test(first)) return false;
  const value = parseInt(first, 16);
  return value >= 0xfe80 && value <= 0xfebf;
}

export function solve(sub: string, sup: string): boolean {
  return lib.subset(sub, sup);
}

export function solve(uuid: string): string | null {
  // Form: 8-4-4-4-12 hex digits (either case), version digit must be 1,
  // variant digit must be 8, 9, a or b (RFC 9562 variant).
  const m = /^([0-9a-f]{8})-([0-9a-f]{4})-1([0-9a-f]{3})-([89ab][0-9a-f]{3})-([0-9a-f]{12})$/i.exec(uuid);
  if (m === null) {
    return null;
  }

  const timeLow = m[1].toLowerCase();   // 32 bits
  const timeMid = m[2].toLowerCase();   // 16 bits
  const timeHi = m[3].toLowerCase();    // 12 bits (version nibble stripped)
  const clockSeq = m[4].toLowerCase();  // clock_seq_hi_and_reserved + clock_seq_low
  const node = m[5].toLowerCase();      // 48 bits

  // 60-bit timestamp as 15 hex digits: time_hi || time_mid || time_low
  const ts = timeHi + timeMid + timeLow;

  // RFC 9562 v6 layout:
  // time_high (32) - time_mid (16) - version(6) + time_low (12) - clock_seq (16) - node (48)
  const timeHigh = ts.slice(0, 8);
  const midV6 = ts.slice(8, 12);
  const lowV6 = ts.slice(12, 15);

  return `${timeHigh}-${midV6}-6${lowV6}-${clockSeq}-${node}`;
}

const SEMVER_RE =
  /^\s*v?(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)(?:-((?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*)(?:\.(?:0|[1-9]\d*|\d*[a-zA-Z-][0-9a-zA-Z-]*))*))?(?:\+([0-9a-zA-Z-]+(?:\.[0-9a-zA-Z-]+)*))?\s*$/

export function solve(installed: string[], range: string): string | null {
  const valid = installed.filter(
    (v): v is string => typeof v === 'string' && SEMVER_RE.test(v)
  )
  return lib.maxSatisfying(valid, range, undefined)
}

export function solve<T>(value: T): T {
  return lib.cloneDeep(value);
}

export function solve(obj: object, updates: [string | (string | number)[], unknown][]): object {
  for (const [path, value] of updates) {
    lib.set(obj, path, value);
  }
  return obj;
}

export function solve(emails: string[]): string[] {
  const seen = new Set<string>();

  const stripSuffix = (local: string): string => {
    const plus = local.indexOf('+');
    return plus >= 0 ? local.slice(0, plus) : local;
  };

  for (const raw of emails) {
    const lower = raw.toLowerCase();
    const at = lower.lastIndexOf('@');
    let canon = lower;

    if (at >= 0) {
      let local = lower.slice(0, at);
      let domain = lower.slice(at + 1);

      if (domain === 'gmail.com' || domain === 'googlemail.com') {
        local = stripSuffix(local);
        // Remove only single dots; keep runs of two or more dots.
        local = local.replace(/(?<!\.)\.(?!\.)/g, '');
        domain = 'gmail.com';
      } else if (
        domain === 'outlook.com' ||
        domain === 'hotmail.com' ||
        domain === 'live.com'
      ) {
        local = stripSuffix(local);
      }

      canon = `${local}@${domain}`;
    }

    seen.add(canon);
  }

  return Array.from(seen);
}

export function solve(word: string, dictionary: string[]): string {
  return lib.closest(word, dictionary);
}

export function solve(text: string): string {
    // Encode the string as UTF-8 bytes manually, so no TextEncoder is needed.
    const bytes: number[] = [];
    for (let i = 0; i < text.length; i++) {
        let cp = text.charCodeAt(i);
        if (cp >= 0xd800 && cp <= 0xdbff && i + 1 < text.length) {
            const lo = text.charCodeAt(i + 1);
            if (lo >= 0xdc00 && lo <= 0xdfff) {
                cp = 0x10000 + ((cp - 0xd800) << 10) + (lo - 0xdc00);
                i++;
            } else {
                cp = 0xfffd; // unpaired high surrogate
            }
        } else if (cp >= 0xd800 && cp <= 0xdfff) {
            cp = 0xfffd; // unpaired low or trailing high surrogate
        }

        if (cp < 0x80) {
            bytes.push(cp);
        } else if (cp < 0x800) {
            bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            bytes.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        } else {
            bytes.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }

    // Delegate the MD5 computation to the library function.
    const digest = lib.md5(new Uint8Array(bytes));

    // Convert the digest bytes to 32 lowercase hex characters.
    return Array.from(digest as ArrayLike<number>, (b) =>
        (b & 0xff).toString(16).padStart(2, "0")
    ).join("");
}

// `lib` is provided by the environment; only its type is declared here.
declare const lib: {
  isURL(url: string, options?: Record<string, unknown>): boolean;
};

const LIB_OPTIONS: Record<string, unknown> = {
  protocols: ['http', 'https'],
  require_protocol: true,
  require_valid_protocol: true,
  require_tld: true,
  require_host: true,
  allow_protocol_relative_urls: false,
  allow_fragments: true,
  allow_query_components: true,
  validate_length: true,
  max_allowed_length: 2048,
};

// Scheme (http or https only) and authority, up to the first '/', '?' or '#'.
const URL_PREFIX = /^(https?):\/\/([^/?#]*)/i;
const LABEL = /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/i;
// Alphabetic TLD, or an IDN punycode TLD (xn--...).
const TLD = /^(?:[a-z]{2,63}|xn--[a-z0-9-]{1,59})$/i;
const PORT = /^[0-9]{1,5}$/;

/** Returns the host portion of an http(s) URL, or null if it cannot be parsed. */
function hostOf(url: string): string | null {
  const match = URL_PREFIX.exec(url);
  if (!match) {
    return null;
  }

  let authority = match[2];

  // Strip userinfo (user:password@).
  const at = authority.lastIndexOf('@');
  if (at !== -1) {
    authority = authority.slice(at + 1);
  }

  // Strip and validate an optional port.
  let host = authority;
  const colon = authority.lastIndexOf(':');
  if (colon !== -1) {
    const port = authority.slice(colon + 1);
    if (!PORT.test(port) || Number(port) > 65535) {
      return null;
    }
    host = authority.slice(0, colon);
  }

  return host;
}

/** True if the host is a fully qualified domain name with a real TLD. */
function isFqdnHost(host: string): boolean {
  if (host.length === 0 || host.length > 253) {
    return false;
  }
  // IPv6 literals are not domain names.
  if (host.startsWith('[')) {
    return false;
  }

  const labels = host.split('.');
  if (labels.length < 2) {
    // Rejects "localhost" and other single-label hosts.
    return false;
  }
  if (!labels.every((label) => LABEL.test(label))) {
    return false;
  }

  // Rejects IPv4 addresses (last label is numeric) and trailing dots (empty label).
  return TLD.test(labels[labels.length - 1]);
}

export function solve(urls: string[]): string[] {
  return urls.filter((url) => {
    if (typeof url !== 'string') {
      return false;
    }
    // Reject any whitespace explicitly.
    if (/\s/.test(url)) {
      return false;
    }
    if (!lib.isURL(url, LIB_OPTIONS)) {
      return false;
    }
    const host = hostOf(url);
    return host !== null && isFqdnHost(host);
  });
}

export function solve(stamps: string[]): number[] {
  const epochs = stamps.map((stamp) => {
    if (typeof stamp !== "string") {
      throw new RangeError(`Invalid date: ${String(stamp)}`);
    }

    // The library treats strings without an offset as local time. The spec
    // requires UTC, so append an explicit "Z" to force the offset code path,
    // which returns a correct instant. Date-only strings get a midnight time.
    const sep = stamp.search(/[Tt ]/);
    let normalized: string;

    if (sep === -1) {
      normalized = `${stamp}T00:00Z`;
    } else {
      const timePart = stamp.slice(sep + 1);
      if (timePart === "") {
        // A dangling separator such as "2024-02-29T" is not valid ISO 8601.
        throw new RangeError(`Invalid date: ${stamp}`);
      }
      const hasOffset = /(?:[Zz]|[+-]\d{2}(?::?\d{2})?)$/.test(timePart);
      normalized = hasOffset ? stamp : `${stamp}Z`;
    }

    const date = lib.parseISO(normalized);
    const ms = date.getTime();
    if (Number.isNaN(ms)) {
      throw new RangeError(`Invalid date: ${stamp}`);
    }
    return ms;
  });

  return epochs.sort((a, b) => a - b);
}

export function solve(name: string, namespace: string): string {
    const hex = namespace.replace(/-/g, "");
    if (!/^[0-9a-fA-F]{32}$/.test(hex)) {
        throw new Error("namespace must be a UUID string");
    }

    const nsBytes: number[] = [];
    for (let i = 0; i < 32; i += 2) {
        nsBytes.push(parseInt(hex.slice(i, i + 2), 16));
    }

    // Manual UTF-8 encoding. Lone surrogates become U+FFFD, matching TextEncoder.
    const nameBytes: number[] = [];
    for (const ch of name) {
        let cp = ch.codePointAt(0) as number;
        if (cp >= 0xd800 && cp <= 0xdfff) {
            cp = 0xfffd;
        }
        if (cp < 0x80) {
            nameBytes.push(cp);
        } else if (cp < 0x800) {
            nameBytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            nameBytes.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        } else {
            nameBytes.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }

    const data = new Uint8Array(nsBytes.length + nameBytes.length);
    data.set(nsBytes, 0);
    data.set(nameBytes, nsBytes.length);

    const digest = lib.sha1(data);
    const b = digest.slice(0, 16);

    // Set version 5 and RFC 4122 variant bits.
    b[6] = (b[6] & 0x0f) | 0x50;
    b[8] = (b[8] & 0x3f) | 0x80;

    let out = "";
    for (let i = 0; i < 16; i++) {
        out += b[i].toString(16).padStart(2, "0");
        if (i === 3 || i === 5 || i === 7 || i === 9) {
            out += "-";
        }
    }
    return out;
}

export function solve(nodes: string[], edges: [string, string][]): string[] {
  return lib.toposort(nodes, edges);
}

export function solve(text: string): number[] {
  const ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

  if (text.length % 4 !== 0) {
    throw new Error(`Invalid base64 length: ${text.length} is not a multiple of 4`);
  }

  const decodeChar = (c: string): number => {
    const idx = ALPHABET.indexOf(c);
    if (idx === -1) {
      throw new Error(`Invalid base64 character: '${c}'`);
    }
    return idx;
  };

  const out: number[] = [];

  for (let i = 0; i < text.length; i += 4) {
    const c0 = text[i];
    const c1 = text[i + 1];
    const c2 = text[i + 2];
    const c3 = text[i + 3];
    const isLastGroup = i + 4 === text.length;

    const pad2 = c2 === "=";
    const pad3 = c3 === "=";

    if (c0 === "=" || c1 === "=") {
      throw new Error("Invalid base64 padding position");
    }
    if (pad2 && !pad3) {
      throw new Error("Invalid base64 padding: '=' must be followed by '='");
    }
    if ((pad2 || pad3) && !isLastGroup) {
      throw new Error("Invalid base64 padding: '=' only allowed at end");
    }

    const v0 = decodeChar(c0);
    const v1 = decodeChar(c1);
    const v2 = pad2 ? 0 : decodeChar(c2);
    const v3 = pad3 ? 0 : decodeChar(c3);

    const n = (v0 << 18) | (v1 << 12) | (v2 << 6) | v3;

    out.push((n >> 16) & 0xff);
    if (!pad2) {
      out.push((n >> 8) & 0xff);
    }
    if (!pad3) {
      out.push(n & 0xff);
    }
  }

  return out;
}

export function solve(epochMs: number): string {
  // Floor to the whole second containing the instant (correct for negative and fractional inputs).
  const whole = Math.floor(epochMs);
  const remainder = ((whole % 1000) + 1000) % 1000;
  const iso = new Date(whole - remainder).toISOString();
  // toISOString always emits milliseconds (".000"); drop them.
  return iso.replace(/\.\d{3}Z$/, "Z");
}

export function solve(a: string, b: string): boolean {
  return lib.intersects(a, b);
}

export function solve(range: string): string | null {
  let result: { version: string } | null;
  try {
    result = lib.minVersion(range);
  } catch (_err) {
    // An invalid range makes the library throw; report that as "no version".
    return null;
  }
  return result ? result.version : null;
}

export function solve(version: string, range: string): boolean {
  return Boolean(lib.gtr(version, range));
}

export function solve(
  version: string,
  kind: 'major' | 'minor' | 'patch' | 'premajor' | 'preminor' | 'prepatch' | 'prerelease',
  id?: string
): string | null {
  return lib.inc(version, kind, id);
}

export function solve(versions: string[]): string[] {
  // Build metadata starts at the first '+'. Prerelease identifiers cannot contain '+'.
  const stripBuild = (v: string): string => {
    const i = v.indexOf('+');
    return i === -1 ? v : v.slice(0, i);
  };

  return [...versions].sort((a, b) => {
    // Precedence (major, minor, patch, prerelease) via the library comparator.
    // Build metadata is removed so the library does not apply its own build ordering.
    const byPrecedence = lib.compareBuild(stripBuild(a), stripBuild(b));
    if (byPrecedence !== 0) return byPrecedence;

    // Versions with equal precedence: order by full string, lexically.
    return a < b ? -1 : a > b ? 1 : 0;
  });
}

export function solve(text: string): string | null {
  const MAX_DIGITS = 16;
  const isDigit = (c: string | undefined): boolean =>
    c !== undefined && c >= "0" && c <= "9";
  const n = text.length;

  let i = 0;
  while (i < n) {
    // Only consider the start of a maximal digit run.
    if (!isDigit(text[i]) || isDigit(text[i - 1])) {
      i++;
      continue;
    }

    // End of the first digit run starting at i.
    let end = i;
    while (end < n && isDigit(text[end])) end++;

    // Collect up to three dot-separated digit runs.
    const parts: string[] = [];
    let valid = true;
    let p = i;
    for (;;) {
      let q = p;
      while (q < n && isDigit(text[q])) q++;
      const part = text.slice(p, q);
      if (part.length > MAX_DIGITS) {
        valid = false;
        break;
      }
      parts.push(part);
      if (parts.length === 3 || text[q] !== "." || !isDigit(text[q + 1])) {
        break;
      }
      p = q + 1;
    }

    if (!valid) {
      // Not a version-like run; resume scanning after its first digit run.
      i = end;
      continue;
    }

    // A leading zero in any number of the first run makes the result null.
    if (parts.some((part) => part.length > 1 && part[0] === "0")) {
      return null;
    }

    return `${parts[0]}.${parts[1] ?? "0"}.${parts[2] ?? "0"}`;
  }

  return null;
}

export function solve(text: string): string {
    // Encode the string as UTF-8 manually (no TextEncoder, since it is not ECMAScript).
    // Lone surrogates are replaced with U+FFFD, matching standard UTF-8 encoding.
    const bytes: number[] = [];
    for (let i = 0; i < text.length; i++) {
        let cp = text.charCodeAt(i);
        if (cp >= 0xd800 && cp <= 0xdbff) {
            const next = i + 1 < text.length ? text.charCodeAt(i + 1) : 0;
            if (next >= 0xdc00 && next <= 0xdfff) {
                cp = 0x10000 + ((cp - 0xd800) << 10) + (next - 0xdc00);
                i++;
            } else {
                cp = 0xfffd;
            }
        } else if (cp >= 0xdc00 && cp <= 0xdfff) {
            cp = 0xfffd;
        }

        if (cp < 0x80) {
            bytes.push(cp);
        } else if (cp < 0x800) {
            bytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            bytes.push(
                0xe0 | (cp >> 12),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        } else {
            bytes.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }

    const digest = lib.sha1(Uint8Array.from(bytes));

    let hex = "";
    for (let i = 0; i < digest.length; i++) {
        const h = digest[i].toString(16);
        hex += h.length < 2 ? "0" + h : h;
    }
    return hex;
}

export function solve(name: string, namespace: string): string {
  const uuidPattern = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
  if (typeof namespace !== "string" || !uuidPattern.test(namespace)) {
    throw new TypeError("namespace must be a valid UUID string");
  }
  return lib.v3(name, namespace).toLowerCase();
}

export function solve(isbn: string, version?: 10 | 13): boolean {
  const s = isbn.replace(/[ -]/g, "");

  const isValid10 = (): boolean => {
    if (!/^[0-9]{9}[0-9X]$/.test(s)) return false;
    let sum = 0;
    for (let i = 0; i < 10; i++) {
      const c = s[i];
      const d = c === "X" ? 10 : c.charCodeAt(0) - 48;
      sum += (10 - i) * d;
    }
    return sum % 11 === 0;
  };

  const isValid13 = (): boolean => {
    if (!/^[0-9]{13}$/.test(s)) return false;
    let sum = 0;
    for (let i = 0; i < 13; i++) {
      const d = s.charCodeAt(i) - 48;
      sum += i % 2 === 0 ? d : 3 * d;
    }
    return sum % 10 === 0;
  };

  if (version === 10) return isValid10();
  if (version === 13) return isValid13();
  return isValid10() || isValid13();
}

export function solve(iban: string): boolean {
  // Ignore spaces and hyphens, and normalise letters to upper case.
  const normalized = iban.replace(/[\s-]+/g, "").toUpperCase();
  return lib.isIBAN(normalized);
}

type IssuerRule = {
  lengths: number[];
  matches: (s: string) => boolean;
};

// True if the first `digits` characters of `s`, read as a number, fall in [lo, hi].
function prefixInRange(s: string, digits: number, lo: number, hi: number): boolean {
  if (s.length < digits) return false;
  const prefix = Number(s.slice(0, digits));
  return prefix >= lo && prefix <= hi;
}

const RANGE_16_19 = [16, 17, 18, 19];
const RANGE_14_19 = [14, 15, 16, 17, 18, 19];

const ISSUERS: IssuerRule[] = [
  // Visa
  {
    lengths: [13, 16, 19],
    matches: (s) => s.startsWith("4"),
  },
  // Mastercard: 51–55 or 2221–2720
  {
    lengths: [16],
    matches: (s) =>
      prefixInRange(s, 2, 51, 55) || prefixInRange(s, 4, 2221, 2720),
  },
  // American Express: 34 or 37
  {
    lengths: [15],
