            out.push(c);
        } else if (c < 0x800) {
            out.push(0xC0 | (c >> 6), 0x80 | (c & 0x3F));
        } else if (c < 0x10000) {
            out.push(
                0xE0 | (c >> 12),
                0x80 | ((c >> 6) & 0x3F),
                0x80 | (c & 0x3F)
            );
        } else {
            out.push(
                0xF0 | (c >> 18),
                0x80 | ((c >> 12) & 0x3F),
                0x80 | ((c >> 6) & 0x3F),
                0x80 | (c & 0x3F)
            );
        }
    }

    const digest = lib.md5(Uint8Array.from(out));

    // Convert the 16 digest bytes to 32 lowercase hex characters.
    return Array.from(digest as ArrayLike<number>, (b: number) =>
        b.toString(16).padStart(2, "0")
