export function solve(nodes: string[], edges: [string, string][]): string[] {
  const index = new Map<string, number>();
  nodes.forEach((name, i) => {
    if (index.has(name)) {
      throw new Error(`Duplicate node: ${name}`);
    }
    index.set(name, i);
  });

  const adj: number[][] = nodes.map(() => []);
  const indegree: number[] = nodes.map(() => 0);

  for (const [a, b] of edges) {
    const ia = index.get(a);
    const ib = index.get(b);
    if (ia === undefined) {
      throw new Error(`Edge references unknown node: ${a}`);
    }
    if (ib === undefined) {
      throw new Error(`Edge references unknown node: ${b}`);
    }
    adj[ia].push(ib);
    indegree[ib]++;
  }

  // Kahn's algorithm; ties are broken by original input order.
  const queue: number[] = [];
  for (let i = 0; i < nodes.length; i++) {
    if (indegree[i] === 0) {
      queue.push(i);
    }
  }

  const result: string[] = [];
  let head = 0;
  while (head < queue.length) {
    const current = queue[head++];
    result.push(nodes[current]);
    for (const next of adj[current]) {
      indegree[next]--;
      if (indegree[next] === 0) {
        queue.push(next);
      }
    }
  }

  if (result.length !== nodes.length) {
    throw new Error("Graph contains a cycle");
  }

  return result;
}

export function solve(name: string, namespace: string): string {
    const nsHex = namespace.replace(/-/g, "");
    if (!/^[0-9a-fA-F]{32}$/.test(nsHex)) {
        throw new Error("namespace must be a UUID string");
    }

    // Namespace UUID as 16 raw bytes.
    const nsBytes: number[] = [];
    for (let i = 0; i < 32; i += 2) {
        nsBytes.push(parseInt(nsHex.slice(i, i + 2), 16));
    }

    // UTF-8 encode the name manually (lone surrogates become U+FFFD).
    const nameBytes: number[] = [];
    for (let i = 0; i < name.length; i++) {
        let cp = name.charCodeAt(i);
        if (cp >= 0xd800 && cp <= 0xdbff) {
            const lo = i + 1 < name.length ? name.charCodeAt(i + 1) : -1;
            if (lo >= 0xdc00 && lo <= 0xdfff) {
                cp = 0x10000 + ((cp - 0xd800) << 10) + (lo - 0xdc00);
                i++;
            } else {
                cp = 0xfffd;
            }
        } else if (cp >= 0xdc00 && cp <= 0xdfff) {
            cp = 0xfffd;
        }

        if (cp < 0x80) {
            nameBytes.push(cp);
        } else if (cp < 0x800) {
            nameBytes.push(0xc0 | (cp >> 6), 0x80 | (cp & 0x3f));
        } else if (cp < 0x10000) {
            nameBytes.push(0xe0 | (cp >> 12), 0x80 | ((cp >> 6) & 0x3f), 0x80 | (cp & 0x3f));
        } else {
            nameBytes.push(
                0xf0 | (cp >> 18),
                0x80 | ((cp >> 12) & 0x3f),
                0x80 | ((cp >> 6) & 0x3f),
                0x80 | (cp & 0x3f)
            );
        }
    }

    // SHA-1 over namespace bytes followed by name bytes.
    const data = new Uint8Array(nsBytes.length + nameBytes.length);
    data.set(nsBytes, 0);
    data.set(nameBytes, nsBytes.length);

    const digest = lib.sha1(data);
    const b = digest.slice(0, 16);

    // Set version (5) and RFC 4122 variant bits.
    b[6] = (b[6] & 0x0f) | 0x50;
    b[8] = (b[8] & 0x3f) | 0x80;

    const hex = Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");
    return (
        hex.slice(0, 8) + "-" +
        hex.slice(8, 12) + "-" +
        hex.slice(12, 16) + "-" +
        hex.slice(16, 20) + "-" +
        hex.slice(20, 32)
    );
