export function solve(range: string): string | null {
  let result: any;
  try {
    result = lib.minVersion(range);
  } catch {
    // Invalid range expressions make the underlying Range constructor throw.
    return null;
  }

  if (!result) {
    return null;
  }

  if (typeof result.version === "string") {
    return result.version;
  }

  const base = `${result.major}.${result.minor}.${result.patch}`;
  return result.prerelease && result.prerelease.length > 0
    ? `${base}-${result.prerelease.join(".")}`
    : base;
}

