export function solve(text: string): string {
    // Manually UTF-8 encode the string (no TextEncoder, which is a browser/Node API).
    // Lone surrogates are replaced with U+FFFD, matching TextEncoder behavior.
    const bytes: number[] = [];
    for (let i = 0; i < text.length; i++) {
        let cp = text.charCodeAt(i);
        if (cp >= 0xd800 && cp <= 0xdbff) {
            const next = i + 1 < text.length ? text.charCodeAt(i + 1) : -1;
