  // is ISO 7064 Mod 11,10, not Verhoeff, so Verhoeff would reject valid numbers.
  const s = id.replace(/[\/\\]/g, '');

  // Exactly 11 digits, first digit not zero
  if (!/^\d{11}$/.test(s)) return false;
  if (s[0] === '0') return false;

  // Among the first 10 digits, exactly one digit may repeat (2 or 3 times);
  // all other digits must be unique.
  const counts = new Array<number>(10).fill(0);
  for (let i = 0; i < 10; i++) counts[+s[i]]++;
  const repeated = counts.filter(c => c > 1);
  if (repeated.length !== 1 || repeated[0] > 3) return false;

  // ISO 7064 Mod 11,10 check digit over the first 10 digits
  let p = 10;
  for (let i = 0; i < 10; i++) {
    let sum = (+s[i] + p) % 10;
    if (sum === 0) sum = 10;
    p = (sum * 2) % 11;
  }
  return (11 - p) % 10 === +s[10];
}

export function solve(id: string): boolean {
  const m = /^(\d{2})(\d{2})(\d{2})\/?(\d{3,4})$/.exec(id);
  if (!m) return false;

  const yy = Number(m[1]);
  const mm = Number(m[2]);
  const dd = Number(m[3]);
  const tail = m[4];

  let year: number;
  if (tail.length === 3) {
    // 9-digit form: only for births before 1954
    if (yy >= 54) return false;
    year = 1900 + yy;
    if (tail === "000") return false;
  } else {
    // 10-digit form: two-digit year below 54 is 20YY, otherwise 19YY
    year = yy < 54 ? 2000 + yy : 1900 + yy;
  }

  // Month decoding: 1-12 (men), 51-62 (women), +20 offsets from 2004 (71-82 for women)
  let month: number;
  let offset20 = false;
  if (mm >= 1 && mm <= 12) {
    month = mm;
  } else if (mm >= 51 && mm <= 62) {
    month = mm - 50;
  } else if (mm >= 21 && mm <= 32) {
    month = mm - 20;
    offset20 = true;
  } else if (mm >= 71 && mm <= 82) {
    month = mm - 70;
    offset20 = true;
  } else {
    return false;
  }
  if (offset20 && year < 2004) return false;

  // Day validity, including leap years
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  if (dd < 1 || dd > daysInMonth[month - 1]) return false;

  if (tail.length === 3) {
    // 9-digit form has no check digit
    return true;
  }

  // 10-digit form: check digit
  const nine = m[1] + m[2] + m[3] + tail.slice(0, 3);
  const check = Number(tail[3]);
  const r = Number(nine) % 11;
  const expected = r === 10 ? 0 : r;
  return check === expected;
}

export function solve(id: string): boolean {
  const s = id.replace(/[\/\\]/g, "");

  // Must be exactly 11 decimal digits, and the first digit must not be 0
  if (!/^[0-9]{11}$/.test(s)) return false;
  if (s[0] === "0") return false;

  const digits = s.split("").map(Number);

  // Among the first 10 digits: no digit may occur more than 3 times,
  // exactly one digit occurs 2 or 3 times, and all other digits occur at most once
  const counts = new Array<number>(10).fill(0);
  for (let i = 0; i < 10; i++) {
    counts[digits[i]]++;
  }
  let repeated = 0;
  for (const c of counts) {
    if (c > 3) return false;
    if (c === 2 || c === 3) repeated++;
  }
  if (repeated !== 1) return false;

  // Check digit (ISO 7064 Mod 11,10)
  let product = 10;
  for (let i = 0; i < 10; i++) {
    let sum = (digits[i] + product) % 10;
    if (sum === 0) sum = 10;
    product = (sum * 2) % 11;
  }
  let check = 11 - product;
  if (check === 10) check = 0;

  return check === digits[10];
}

export function solve(egn: string): boolean {
  // Must be exactly 10 ASCII digits.
  if (typeof egn !== "string" || !/^[0-9]{10}$/.test(egn)) {
    return false;
  }

  const digit = (i: number): number => egn.charCodeAt(i) - 48; // '0' is char code 48

  // Birth date YYMMDD. The month field encodes the century:
  // 01-12 -> 1900s, 21-32 -> 1800s, 41-52 -> 2000s, 61-72 -> 2100s.
  const yy = digit(0) * 10 + digit(1);
  let month = digit(2) * 10 + digit(3);
  const day = digit(4) * 10 + digit(5);

  let century: number;
  if (month >= 1 && month <= 12) {
    century = 1900;
  } else if (month >= 21 && month <= 32) {
    century = 1800;
    month -= 20;
  } else if (month >= 41 && month <= 52) {
    century = 2000;
    month -= 40;
  } else if (month >= 61 && month <= 72) {
    century = 2100;
    month -= 60;
  } else {
    return false;
  }

  const year = century + yy;
  const isLeap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;

  let daysInMonth: number;
  switch (month) {
    case 2:
      daysInMonth = isLeap ? 29 : 28;
      break;
    case 4:
    case 6:
    case 9:
    case 11:
      daysInMonth = 30;
      break;
    default:
      daysInMonth = 31;
  }
  if (day < 1 || day > daysInMonth) {
    return false;
  }

  // Check digit: weighted sum of the first nine digits modulo 11;
  // a remainder of 10 is encoded as 0.
  const weights = [2, 4, 8, 5, 10, 9, 7, 3, 6];
  let sum = 0;
  weights.forEach((w, i) => {
    sum += digit(i) * w;
  });
  const remainder = sum % 11;
  const checkDigit = remainder === 10 ? 0 : remainder;

  return checkDigit === digit(9);
}

