  const dd = match[3];
  const serial = match[4];
  const yearTwoDigits = Number(yy);

  let year: number;

  if (serial.length === 3) {
    // 9-digit form: only for numbers issued before 1954
    if (yearTwoDigits >= 54) return false;
    if (serial === "000") return false;
    year = 1900 + yearTwoDigits;
  } else {
    // 10-digit form: check digit required
    year = yearTwoDigits < 54 ? 2000 + yearTwoDigits : 1900 + yearTwoDigits;

    const digits = yy + mm + dd + serial;
    let n = 0;
    for (let i = 0; i < 9; i++) {
      n = n * 10 + (digits.charCodeAt(i) - 48);
    }
    const remainder = n % 11;
    const expected = remainder === 10 ? 0 : remainder;
    const check = digits.charCodeAt(9) - 48;
    if (check !== expected) return false;
  }

  // Decode month: men 1-12, women +50, from 2004 +20 (men), +70 (women)
  const rawMonth = Number(mm);
  let month: number;
  if (rawMonth >= 71) {
    month = rawMonth - 70;
  } else if (rawMonth >= 51) {
    month = rawMonth - 50;
  } else if (rawMonth >= 21) {
    month = rawMonth - 20;
  } else {
    month = rawMonth;
  }
  if (month < 1 || month > 12) return false;

  // Validate day for the month, including leap years
  const leap = (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const daysInMonth = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  const day = Number(dd);
  if (day < 1 || day > daysInMonth[month - 1]) return false;

  return true;
}

export function solve(id: string): boolean {
  // Remove slashes and backslashes, then require exactly 11 ASCII digits.
  const s = id.replace(/[\/\\]/g, "");
  if (!/^[0-9]{11}$/.test(s)) return false;

  // The first digit must not be zero.
  if (s[0] === "0") return false;

  // Among the first 10 digits: exactly one digit occurs 2 or 3 times,
  // and no digit occurs more than 3 times.
  const counts = new Array<number>(10).fill(0);
  for (let i = 0; i < 10; i++) {
    counts[Number(s[i])]++;
  }
  let repeated = 0;
  for (const n of counts) {
    if (n > 3) return false;
    if (n === 2 || n === 3) repeated++;
  }
  if (repeated !== 1) return false;

  // Check digit (ISO 7064 MOD 11,10 variant used for the Steuer-ID).
  let product = 10;
  for (let i = 0; i < 10; i++) {
    let sum = (Number(s[i]) + product) % 10;
    if (sum === 0) sum = 10;
    product = (sum * 2) % 11;
  }
  let check = 11 - product;
  if (check === 10) check = 0;

  return check === Number(s[10]);
}

