function canonicalize(raw: string): string {
  const email = raw.toLowerCase();
  const at = email.lastIndexOf("@");
  if (at < 0) {
    return email;
  }

  let local = email.slice(0, at);
  const domain = email.slice(at + 1);
  const plus = local.indexOf("+");

  if (domain === "gmail.com" || domain === "googlemail.com") {
    if (plus >= 0) {
      local = local.slice(0, plus);
    }
    // Remove single dots only; keep runs of two or more dots intact.
    local = local.replace(/\.+/g, (run) => (run.length === 1 ? "" : run));
    return `${local}@gmail.com`;
  }

  if (["outlook.com", "hotmail.com", "live.com"].includes(domain)) {
    if (plus >= 0) {
      local = local.slice(0, plus);
    }
    return `${local}@${domain}`;
  }

  return email;
}

export function solve(id: string): boolean {
  // Remove slashes and backslashes.
  const s = id.replace(/[\/\\]/g, "");

  // 11 digits, first digit must not be 0.
  if (!/^[1-9]\d{10}$/.test(s)) return false;

  const digits = s.slice(0, 10).split("").map(Number);

  // Repeated-digit rule for the first 10 digits:
  // no digit may occur more than 3 times, and exactly one digit may repeat
  // (occur 2 or 3 times); all other digits occur at most once.
  const counts = new Array<number>(10).fill(0);
  for (const d of digits) counts[d]++;
  let repeated = 0;
  for (const c of counts) {
    if (c > 3) return false;
    if (c >= 2) repeated++;
  }
  if (repeated !== 1) return false;

  // Check digit: ISO 7064 Mod 11,10 over the first 10 digits.
  // (lib.verhoeffCheck is not used here because the German IdNr check digit
  // is defined by ISO 7064 Mod 11,10, not by the Verhoeff algorithm.)
  let product = 10;
  for (const d of digits) {
    let sum = (d + product) % 10;
    if (sum === 0) sum = 10;
    product = (sum * 2) % 11;
  }
  const check = (11 - product) % 10;

  return check === Number(s[10]);
}

