  const colon = authority.lastIndexOf(':');
  return colon === -1 ? authority : authority.slice(0, colon);
}

// A fully qualified domain name: at least two labels, valid label characters,
// and a alphabetic (or punycode) top-level domain.
function isFQDN(host: string): boolean {
  if (!host) return false;
  const labels = host.split('.');
  if (labels.length < 2) return false;
  if (!labels.every((label) => LABEL_RE.test(label))) return false;
  return TLD_RE.test(labels[labels.length - 1]);
}

export function solve(urls: string[]): string[] {
  return urls.filter((url) => {
